content:
{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 2,
      "verse": 1,
      "text_ar": "قال الرب: أنا أخرجت هذا الشعب من القُبْضة والعبودية. أنا آتيتهم أحكامي عبرُ خدمي الأنبياء، فلم يسمعوا لهم وأبطلوا مشيئتي.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 2,
      "text_ar": "قالت لهم أمهم التي ولدتهم: اذهبوا طريقكم يا أبنائي، فأنا أرملة متروكة.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 3,
      "text_ar": "ربيتكم بالفرح، وضعتكم بالحُزن والأسى، لأنكم خطيتم أمام الرب الإله، وفعلتم ما هو شرير أمامي.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 4,
      "text_ar": "ولكن ما الذي أستطيع فعله لأمكم؟ أنا أرملة متروكة. اذهبوا يا أبنائي طريقكم، واطلبوا رحمة من الرب.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 5,
      "text_ar": "أما أنا يا أبت، فأنا أدعو عليك كشاهد إضافةً إلى أم هؤلاء الأطفال، لأنهم لم يحافظوا على عهدي.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 6,
      "text_ar": "لكي تجعلهم في بلبلة، وأمهم في تخريب، فلا يكون لهم نسل.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 7,
      "text_ar": "ليشتتوا بين الأمم، وتُمحى أسمائهم من على الأرض، لأنهم احتقرّوا عهدي.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 8,
      "text_ar": "ويلٌ لكِ يا آشور، التي تتسترين بالظالمين معك! أيها الشعب الشرير، اذكُر ما فعلتُه بسَدوم وعمورة،",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 9,
      "text_ar": "فأرضهما أصبحت كتلاً من القار، وأكواماً من الرماد. ذلك ما سأفعله أيضاً بالذين لم يسمعوا لي، قال الرب الق大力.",
      "review_notes_ar": ["تصحيح: 'الق大力' - كتابة خاطئة، يجب أن تكون 'القدوسين' وفقاً للسياق أو 'الرب القدير' حسب النسخ المعتمدة من 2 أستير/سفر ابن صوريان الثاني، هنا سأصحح في المخرجات النهائية."]
    },
    {
      "chapter": 2,
      "verse": 10,
      "text_ar": "قال الرب لعازر: قِل لشعبي أني سأعطيهم مملكة أورشليم، التي كنت سأعطيها لإسرائيل.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 11,
      "text_ar": "وسأستعيد مجدي لنفسي، وأعطيهؤلاء المسكنُ الأبدي الذي جهزته لهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 12,
      "text_ar": "سيملكون شجرة الحياة كمُعطّر عطر، ولن يتعبوا ولن يملّوا.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 13,
      "text_ar": "اسألوا وستُدفع لكم، تصدقوا كي تقل أعماركم، وليقصر عمركم. المملكة معده بالفعل لكم. اسهروا!",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 14,
      "text_ar": "ادعُ السماء والأرض شهوداً. ادعُهما شهودين، لأنني تركت الشر، وابتدأت الخير، لأنني حي، قال الرب.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 15,
      "text_ar": "يا أم الأبنياء، احضني أبناءك. سأجلبهم بالفرح كما تفعل الحمامة. ثبّتوا أقدامهم، لأنني اخترتك، قال الرب.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 16,
      "text_ar": "سأقيمُ الموتى من أماكنهم، وأخرجهم من قبورهم، لأنني أعترف باسمي فيهم.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 17,
      "text_ar": "لا تخافي، يا أم الأبناء، لأنني قد اخترتك، قال الرب.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 18,
      "text_ar": "لأجلك سنرتفع، سأرسل عبادي إشعياء ويَرميا، وبعد مشورتهما قَدَّستُ لكِ وأعددتُ اثنتي عشرة شجرة محملة بثمرات متنوعة،",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 19,
      "text_ar": "وعدداً من العيون المتدفقة بالحليب والعسل، وسبع جبال كبيرة ينبت فيها الورد والياسمين، بها سأملأ أبنائك بالفرح.",
      "review_notes_ar": []
    },
    {
      "chapter": 2,
      "verse": 20,
      "text_ar": "احكمي بالعدل للأرملة. اتصّلي بحق اليتيم. أعطي الضعفاء. دافعي عن اليتيم. علمّي عاريتهم.",
      "review_notes_ar": []
    }
  ]
}
